// Rearrange options so correct answer letters are NEVER consecutive
function rearrangeQuestionOptions(question, targetCorrectLetter) {
    const originalOptions = [...question.options];
    const originalCorrectLetter = question.answer;
    const correctText = originalOptions.find(opt => opt[0] === originalCorrectLetter).slice(3);
    const otherTexts = originalOptions.filter(opt => opt[0] !== originalCorrectLetter).map(opt => opt.slice(3));
    
    const letters = "ABCDEFGHIJ".split("");
    const targetIndex = letters.indexOf(targetCorrectLetter);
    
    // Build new options: correct answer at target position, others fill randomly
    const newOptions = [];
    const usedIndices = new Set([targetIndex]);
    
    // Place correct answer at target position
    newOptions[targetIndex] = `${targetCorrectLetter}. ${correctText}`;
    
    // Randomly place remaining options in empty slots
    const remainingIndices = [];
    for (let i = 0; i < letters.slice(0, originalOptions.length).length; i++) {
        if (!usedIndices.has(i)) remainingIndices.push(i);
    }
    remainingIndices.sort(() => Math.random() - 0.5);
    
    otherTexts.forEach((text, i) => {
        const pos = remainingIndices[i];
        newOptions[pos] = `${letters[pos]}. ${text}`;
    });
    
    return { ...question, options: newOptions, answer: targetCorrectLetter };
}

// Assign correct letters so NO two in a row are the same
function generateNonConsecutiveCorrectPattern(questions) {
    const letters = "ABCDEFGHIJ".split("");
    const maxLetter = Math.max(...questions.map(q => q.options.length));
    const availableLetters = letters.slice(0, maxLetter);
    
    let lastLetter = "";
    return questions.map(q => {
        let newLetter;
        do {
            newLetter = availableLetters[Math.floor(Math.random() * availableLetters.length)];
        } while (newLetter === lastLetter); // ✅ NEVER same as previous
        lastLetter = newLetter;
        return rearrangeQuestionOptions(q, newLetter);
    });
}
