let examData, currentQ = 0, userAnswers = [], timer = null, timeLeft = 0, examMode = "medium";

// ✅ KATEX RENDER HELPER
function renderAllMath() {
    if (!window.renderMathInElement) return;
    try {
        renderMathInElement(document.body, {
            delimiters: [
                {left: "\\(", right: "\\)", display: false},
                {left: "\\[", right: "\\]", display: true}
            ],
            throwOnError: false
        });
    } catch (e) { console.log("Math render:", e.message); }
}

// ✅ RUN ON PAGE LOAD — FIX OPTIONS ONCE AT START
window.addEventListener("load", () => {
    try {
        examData = JSON.parse(localStorage.getItem("currentExam") || "null");
        if (!examData) throw new Error("Pick a course first!");
        examMode = examData.mode || "medium";

        document.getElementById("examCourseName").textContent = `📚 ${examData.subName} EXAMINATION`;

        const active = JSON.parse(localStorage.getItem("cbtActive") || "null");
        if (!active) throw new Error("Login required!");

        const allUsers = JSON.parse(localStorage.getItem("cbtalluser") || "[]");
        window.currentUser = allUsers.find(u => u.matric === active.matric);
        if (!currentUser) throw new Error("User not found — re‑register/login.");

        let qBank = [...(fullQuestionBank[examData.subId] || [])];
        
        // 🆕 FILTER BY SELECTED TOPICS
        if(examData.topics && examData.topics.length > 0 && !examData.topics.includes("ALL")){
            qBank = qBank.filter(q=> examData.topics.includes(q.topic || "General"));
        }

        if (!qBank.length) throw new Error(`No questions found for selected topic(s)!`);
        while (qBank.length < examData.qCount) qBank = [...qBank, ...qBank];
        examData.questions = [...qBank].sort(() => Math.random() - 0.5).slice(0, examData.qCount);

        // ✅ APPLY PATTERN ONCE — OPTIONS BECOME STABLE
        examData.questions = generateNonConsecutiveCorrectPattern(examData.questions);

        userAnswers = Array(examData.qCount).fill(null);
        timeLeft = examData.time;

        document.getElementById("examPic").src = currentUser.profilePic;
        document.getElementById("examFirstname").textContent = currentUser.firstname;
        document.getElementById("examMatric").textContent = currentUser.matric;

        renderNav();
        showQuestion();
        if (timeLeft > 0) startTimer();
        else document.getElementById("timer").textContent = "∞ Unlimited";

    } catch (err) {
        alert("❌ " + err.message);
        location.href = "index.html";
    }
});

function startTimer() {
    if (timer) clearInterval(timer);
    timer = setInterval(() => {
        if (timeLeft <= 0) {
            clearInterval(timer);
            alert("⏱️ TIME UP! Exam will submit automatically.");
            submitExam();
            return;
        }
        timeLeft--;
        const m = Math.floor(timeLeft / 60);
        const s = timeLeft % 60;
        document.getElementById("timer").textContent = `${m}:${s < 10 ? "0" + s : s}`;
    }, 1000);
}

function showQuestion() {
    const q = examData.questions[currentQ]; // ✅ FIXED — NO RE-SHUFFLE
    const sel = userAnswers[currentQ];
    document.getElementById("questionBox").innerHTML = `
        <h3>Q${currentQ+1}: ${q.question}</h3>
        ${q.image ? `<img src="${q.image}" alt="Question Image" class="question-img">` : ""}
        <div class="options-list">
            ${q.options.map(opt => `
                <label class="option ${sel === opt[0] ? "selected" : ""}">
                    <input type="radio" name="ans" value="${opt[0]}" 
                           ${sel === opt[0] ? "checked" : ""}
                           data-answer="${q.answer}"
                           data-explanation="${q.explanation}"
                           onchange="saveAns('${opt[0]}')${examMode === 'instant' ? `;showFeedback(this)` : ''}">
                    ${opt}
                </label>`).join("")}
        </div>`;
    document.getElementById("prevBtn").disabled = currentQ === 0;
    document.getElementById("nextBtn").textContent = currentQ === examData.questions.length - 1 ? "✅ Finish(scroll down)" : "Next ➡️";
    
    setTimeout(renderAllMath, 30);
}

// ✅ FEEDBACK SYSTEM
function showFeedback(input) {
    const selected = input.value;
    const correct = input.dataset.answer;
    const exp = input.dataset.explanation;

    const fb = document.getElementById("instantFeedback");
    fb.style.display = "block";
    fb.className = `feedback-box ${selected === correct ? "correct" : "wrong"}`;
    fb.innerHTML = `<strong>${selected === correct ? "✅ CORRECT" : "❌ WRONG"}</strong><br>📌 ${exp}`;
    
    setTimeout(renderAllMath, 30);
}

function toggleCalc() { document.getElementById("calcPanel").classList.toggle("show"); }
function calcInput(v) { document.getElementById("calcDisplay").value += v; }
function calcClear() { document.getElementById("calcDisplay").value = ""; }
function calcBack() { document.getElementById("calcDisplay").value = document.getElementById("calcDisplay").value.slice(0, -1); }
function calcEquals() {
    try {
        let d = document.getElementById("calcDisplay").value
            .replace(/sin/g, "Math.sin").replace(/cos/g, "Math.cos")
            .replace(/tan/g, "Math.tan").replace(/sqrt/g, "Math.sqrt")
            .replace(/log/g, "Math.log10").replace(/ln/g, "Math.log")
            .replace(/pi/g, "Math.PI").replace(/\^/g, "**");
        document.getElementById("calcDisplay").value = eval(d);
    } catch { alert("Calculation error!"); }
}

function saveAns(v) { userAnswers[currentQ] = v; updateNavStyle(); showQuestion(); }
function prevQ() { if (currentQ > 0) { currentQ--; showQuestion(); } }
function nextQ() { if (currentQ < examData.questions.length - 1) { currentQ++; showQuestion(); } }

function renderNav() {
    const n = document.getElementById("qNav"); n.innerHTML = "";
    for (let i = 0; i < examData.questions.length; i++) {
        const b = document.createElement("button");
        b.className = "q-btn"; b.textContent = i + 1;
        b.onclick = () => { currentQ = i; showQuestion(); };
        n.appendChild(b);
    }
}

function updateNavStyle() {
    document.querySelectorAll(".q-btn").forEach((b, i) => {
        b.classList.remove("answered");
        if (userAnswers[i]) b.classList.add("answered");
    });
}

function confirmSubmit() {
    if (confirm("⚠️ Are you sure you want to submit? You cannot change answers after this!")) submitExam();
}

function submitExam() {
    if (timer) clearInterval(timer);
    const score = userAnswers.filter((a, i) => a === examData.questions[i].answer).length;
    currentUser.exams.push({
        subject: examData.subName, score, userAnswers,
        questions: examData.questions, timeLeft: Math.round(timeLeft / 60),
        date: new Date().toLocaleString()
    });
    const all = JSON.parse(localStorage.getItem("cbtalluser"));
    all.splice(all.findIndex(u => u.matric === currentUser.matric), 1, currentUser);
    localStorage.setItem("cbtalluser", JSON.stringify(all));
    alert(`✅ Exam Submitted!\nScore: ${score}/${examData.questions.length} (${Math.round(score/examData.questions.length*100)}%)`);
    location.href = "index.html";
}
